yakit.AutoInitYakit()

# Input your code!

url := cli.String("url",cli.setRequired(true))
proxy := cli.String("proxy")
env := cli.String("env")
thread = cli.Int("thread", cli.setDefault(10))
allowMethod := cli.String("method",cli.setDefault("get,post,put"),cli.setRequired(true))

reqList = []
err := ""


checkFingerPrint = func(resp){
    fingerPrint := {"swagger2":"swagger","openapi3":"openapi"}
    content_type = resp.GetHeader("content-type")
    body = resp.Data()
    if !str.Contains(content_type,"json"){
        yakit.Info("%v 不是swagger文档！", url)
        os.Exit(0)
    }
    for k, v = range fingerPrint{
        if str.Contains(body,v){
            yakit.Info("检测到swagger版本为:%v", k)
            return k
        }
    }
    yakit.Info("未识别到api文档类型！")
}
addReq = func(method,env,path,content_type,body,proxy){
    url := env + path
    req := ""
    if proxy != ""{
        req, err = http.NewRequest(method, url, http.timeout(3), http.proxy(proxy),http.ua(http.uarand()),http.header("Content-type", content_type),http.body(body))
    }else{
        req, err = http.NewRequest(method, url, http.timeout(3), http.ua(http.uarand()),http.header("Content-type", content_type),http.body(body))
    }
    if err != nil{
        yakit.Info("生成 %v 的http请求失败", url)
        return 
    }
    reqList = append(reqList, req)
}

swagger2Req = func(resp){
    bodyJson := json.loads(resp.Data())
    if env == ""{
        u = str.ParseStringUrlToUrlInstance(url)~
        basePath = bodyJson["basePath"]
        if basePath != nil{
            env = u.Scheme + "://" + u.Host + basePath
        }else{
            env = u.Scheme + "://" + u.Host
        }
    }
    paths := bodyJson["paths"]
    if paths == nil{
        yakit.Info("获取api-docs路由为空！")
        os.Exit(0)
    }
    paramsMap := {}
    definitions = bodyJson["definitions"]
    if definitions != nil{
        for name, v1 = range definitions{
            tparam := {}
            properties = v1["properties"]
            if properties != nil{
                for k, v2 = range properties{
                    if v2["type"] != nil && v2["type"] == "integer"{
                        tparam[k] = randn(1,100)
                    }else if v2["type"] != nil && v2["type"] == "boolean"{
                        tparam[k] = true
                    }else{
                        tparam[k] = randstr(5)
                    }
                }
            }
            paramsMap[name] = tparam
        }

    }

    for path, value1 = range paths{
        for method, value2 = range value1{
            if !str.Contains(allowMethod,method){
                continue
            }
            content_type := "application/x-www-form-urlencoded"
            getParams := {}
            postParams := {}
            uri := path
            if value2["consumes"] != nil{
                content_type = value2["consumes"][0]
            }
            if value2["parameters"] == nil{
                addReq(str.ToUpper(method),env,uri,content_type,"",proxy)
                continue
            }
            for _, param = range value2["parameters"]{
                if param["in"] == "query"{
                    if param["type"] != nil && param["type"] == "integer"{
                        getParams[param["name"]] = randn(1, 100)
                    }else if param["type"] != nil && param["type"] == "boolean"{
                        getParams[param["name"]] = true
                    }else{
                        getParams[param["name"]] = randstr(5)
                    }

                }else if param["in"] == "path"{
                    if param["type"] != nil && param["type"] == "integer"{
                        uri = str.Replace(uri,"{"+param["name"]+"}",string(randn(1, 100)),1)
                    } else{
                        uri = str.Replace(uri,"{"+param["name"]+"}",randstr(5), 1)
                    }
                }else if param["in"] == "body"{
                    if param["type"] != nil && param["type"] == "integer"{
                        postParams[param["name"]] = randn(1, 100)
                    }else if param["type"] != nil && param["type"] == "boolean"{
                        postParams[param["name"]] = true
                    }else{
                        if param["schema"] != nil{
                            if param["schema"]["$ref"] != nil {
                                ref = param["schema"]["$ref"]
                                ref1 = str.Split(ref,"/")
                                ref = ref1[len(ref1)-1:]
                                postParams = paramsMap[ref[0]]
                            }
                        }else{
                            postParams[param["name"]] = randstr(5)
                        }
                    }
                }
            }
            if len(postParams) > 0{
                if str.Contains(content_type,"json"){
                    postParams = json.dumps(postParams)
                }else{
                    tmp = ""
                    for k,v = range postParams{
                        tmp += k + "=" + string(v) + "&"
                    }
                    tmp = tmp[:-1]
                    postParams = tmp
                }
            }else{
                postParams = ""
            }

            if len(getParams) > 0{
                tmp = "?"
                for k,v = range getParams{
                    tmp += k + "=" + string(v) + "&"
                }
                tmp = tmp[:-1]
                getParams = tmp
            }else{
                getParams = ""
            }
            uri = uri + getParams
            addReq(str.ToUpper(method),env,uri,content_type,postParams,proxy)
        }
    }
}

yakit.EnableTable("Swagger Api", ["方法","状态码","长度","URL"])

sendReq = func(wg,req){
    wg.Add()
    go func{
        defer wg.Done()
        tmpMap := {}
        resp, err = http.Do(req)
        if err != nil{
            yakit.Info("%v 请求失败", req.Request.URL.String())
            return
        }
        tmpMap["状态码"] = resp.Status
        tmpMap["方法"] = req.Request.Method
        tmpMap["长度"] = resp.ContentLength
        tmpMap["URL"] = req.Request.URL.String()
        yakit.Output(yakit.TableData("Swagger Api", tmpMap))
    }
}

openapi3Req = func(resp){
    bodyJson := json.loads(resp.Data())
    if env == ""{
        servers = bodyJson["servers"]
        u = str.ParseStringUrlToUrlInstance(url)~
        if servers != nil{
            env = servers[0]["url"]
            if env == nil{
                env = u.Scheme + "://" + u.Host
            }
        }else{
            env = u.Scheme + "://" + u.Host
        }
    }
    paths := bodyJson["paths"]
    if paths == nil{
        yakit.Info("获取api-docs路由为空！")
        os.Exit(0)
    }
    paramsMap := {}
    components = bodyJson["components"]
    if components != nil{
        schemas = components["schemas"]
        if schemas != nil{
            for name, v1 = range schemas{
                tparam := {}
                properties = v1["properties"]
                if properties != nil{
                    for k, v2 = range properties{
                        if v2["type"] != nil && v2["type"] == "integer"{
                            tparam[k] = randn(1,100)
                        }else if v2["type"] != nil && v2["type"] == "boolean"{
                            tparam[k] = true
                        }else{
                            tparam[k] = randstr(5)
                        }
                    }
                    paramsMap[name] = tparam
                }


            }
        }

    }

    for path, value1 = range paths{
        for method, value2 = range value1{
            if !str.Contains(allowMethod,method){
                continue
            }
            content_type := "application/json"
            getParams := {}
            postParams := {}
            uri := path
            if value2["parameters"] == nil && value2["requestBody"] == nil{
                addReq(str.ToUpper(method),env,uri,content_type,"",proxy)
                continue
            }

            if value2["parameters"] != nil{
                for _, param = range value2["parameters"]{
                    if param["in"] == "query"{
                        if param["schema"] != nil{
                            if param["schema"]["type"] != nil && param["schema"]["type"] == "integer"{
                                getParams[param["name"]] = randn(1,100)
                            }else if param["schema"]["type"] != nil && param["schema"]["type"] == "boolean"{
                                getParams[param["name"]] = true
                            }else{
                                 getParams[param["name"]] = randstr(5)
                            }
                        }else{
                            getParams[param["name"]] = randstr(5)
                        }
                    }else if param["in"] == "path"{
                        if param["schema"] != nil{
                            if param["schema"]["type"] != nil && param["schema"]["type"] == "integer"{
                                uri = str.Replace(uri,"{"+param["name"]+"}",string(randn(1,100)), 1)
                            }else{
                                 getParams[param["name"]] = randstr(5)
                            }
                        }else{
                            uri = str.Replace(uri,"{"+param["name"]+"}",randstr(5), 1)
                        }
                    }
                }                
            }
            if value2["requestBody"] != nil {
                for ctype, value3 = range value2["requestBody"]["content"]{
                    content_type = ctype
                    i=  x.Keys(value3["schema"])
                    if i[0] == "$ref"{
                        ref = value3["schema"]["$ref"]
                        ref1 = str.Split(ref,"/")
                        ref = ref1[len(ref1)-1:]
                        postParams = paramsMap[ref[0]]
                    }
                }
            }
            if len(getParams) > 0{
                tmp = "?"
                for k,v = range getParams{
                    tmp += k + "=" + string(v) + "&"
                }
                tmp = tmp[:-1]
                getParams = tmp
            }else{
                getParams = ""
            }
            if len(postParams) > 0{
                postParams = json.dumps(postParams)
            }else{
                postParams = ""
            }
            uri = uri + getParams
            addReq(str.ToUpper(method),env,uri,content_type,postParams,proxy)
        }
    }
}

main := func(url){
    wg := sync.NewSizedWaitGroup(thread)
    resp := ""
    if proxy != ""{
        resp, err = http.Get(url, http.proxy(proxy), http.timeout(3),http.ua(http.uarand()))
    }else{
        resp, err = http.Get(url, http.timeout(3),http.ua(http.uarand()))
    }
    if err !=nil{
        yakit.Info("%v 请求失败！", url)
        os.Exit(0)
    }
    swaggerFingerPrint = checkFingerPrint(resp)
    if swaggerFingerPrint == "swagger2"{
        swagger2Req(resp)
    }else if swaggerFingerPrint == "openapi3"{
        openapi3Req(resp)
    }
    if len(reqList) == 0{
        yakit.Info("未发现请求包！")
        return 
    }
    for _, r = range reqList{
        sendReq(wg,r)
    }
    wg.Wait()
}
main(url)
